import (
	context "context"
	fern "github.com/openapi-path-param-body-collision/fern"
	fernclient "github.com/openapi-path-param-body-collision/fern/client"
)

client := fernclient.NewClient()
response, err := client.UpdateProfileIdentifier(
	context.TODO(),
	&fern.IdentifierUpdate{
		ProfileID:       "profile_123",
		IDTypePathParam: "email",
		IDType:          "phone",
		OldValue:        "+13175556789",
		NewValue:        "+13175556798",
	},
)
